// === Tab: Boid ===
class Boid {

  constructor(index,x, y) {
		this.index=index;
    this.location=new p5.Vector(x,y);
    this.acceleration = new p5.Vector(random(-2, 2), random(-2, 2));
    this.velocity = new p5.Vector(0, 0);
    this.radius = random(15, 100);
    this.wandertheta = 0;
    this.maxspeed = random(5, 12);
    this.maxforce = random(0.02, 1);
    this.dia=2*this.radius;
    this.wanderR = random(10,50);         // Radius for the "wander circle"
    this.wanderD = random(30,200);         // Distance from the "wander circle"
    this.maxchange = 0.7;
  }
  run(){
    this.update();
    this.borders();
    this.wander();
  }
  // Method to update location
  update() {
    // Update velocity
   this.velocity.add(this.acceleration);
    // Limit speed
   this.velocity.limit(this.maxspeed);
    this.location.add(this.velocity);
    if (random(1)>.995) {
      this.location=new p5.Vector(this.location.x,this.location.y);
    }
  }

  wander() {
    this.wandertheta += random(-this.maxchange, this.maxchange);     // Randomly change wander theta

    // Now we have to calculate the new location to steer towards on the wander circle
    this.circleloc =this.velocity.copy();    // Start with velocity
    this.circleloc.normalize();            // Normalize to get heading
    this.circleloc.mult(this.wanderD);          // Multiply by distance
    this.circleloc.add(this.location);               // Make it relative to boid's location

    var h =this.velocity.heading();        // We need to know the heading to offset wandertheta

    this.circleOffSet = new p5.Vector(this.wanderR*cos(this.wandertheta+h), this.wanderR*sin(this.wandertheta+h));
    this.target = p5.Vector.add(this.circleloc, this.circleOffSet);
		//this.deviation=p5.Vector.sub(boids[(this.index+1)%nboids].location,this.location).normalize().mult(this.radius);
		//this.target=p5.Vector.add(this.target,this.deviation);//p5.Vector.add(this.location,this.deviation);//
    this.seek(this.target);
  }  

  applyForce(force) {
    // We could add mass here if we want A = F / M
    this.acceleration.add(force);
  }


  // A method that calculates and applies a steering force towards a target
  // STEER = DESIRED MINUS VELOCITY
  seek(target) {
    var desired = p5.Vector.sub(target, this.location);  // A vector pointing from the location to the target
    // Normalize desired and scale to maximum speed
    desired.normalize();
    desired.mult(this.maxspeed);
    // Steering = Desired minus Velocity
    var steer = p5.Vector.sub(desired,this.velocity);
    steer.limit(this.maxforce);  // Limit to maximum steering force

    this.applyForce(steer);
  }

  // Wraparound
  borders() {
    if (this.location.x < -this.radius) this.location.x = width+this.radius;
    if (this.location.y < -this.radius) this.location.y = height+this.radius;
    if (this.location.x > width+this.radius) this.location.x = -this.radius;
    if (this.location.y > height+this.radius) this.location.y = -this.radius;
  }
  display(){
    moflayer.fill(255,100);
    moflayer.strokeWeight(1);
    moflayer.ellipse(this.location.x,this.location.y,this.radius,this.radius);
    //moflayer.strokeWeight(.5);
    moflayer.noStroke();
    moflayer.fill(255,0,0,80);
    moflayer.ellipse(this.circleloc.x,this.circleloc.y,2*this.wanderR,2*this.wanderR);
    moflayer.strokeWeight(2);
    moflayer.stroke(0);
    moflayer.line(this.location.x,this.location.y,this.target.x,this.target.y);
  }
}

